    entry = JournalEntry(user_id=test_user_id, entry_date=date.today(), memo='Valid salary entry', source_type=JournalEntrySourceType.MANUAL, status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add(JournalLine(journal_entry_id=entry.id, account_id=asset_account.id, direction=Direction.DEBIT, amount=Decimal('5000.00'), currency='SGD')); db.add(JournalLine(journal_entry_id=entry.id, account_id=income_account.id, direction=Direction.CREDIT, amount=Decimal('5000.00'), currency='SGD')); await db.commit(); assert await verify_accounting_equation(db, test_user_id, base_currency='SGD') is True; bad_entry = JournalEntry(user_id=test_user_id, entry_date=date.today(), memo='Intentionally unbalanced entry', source_type=JournalEntrySourceType.MANUAL, status=JournalEntryStatus.POSTED); db.add(bad_entry); await db.flush(); db.add_all([JournalLine(journal_entry_id=bad_entry.id, account_id=asset_account.id, direction=Direction.DEBIT, amount=Decimal('1000.00'), currency='SGD'), JournalLine(journal_entry_id=bad_entry.id, account_id=income_account.id, direction=Direction.CREDIT, amount=Decimal('999.00'), currency='SGD')])
    with pytest.raises(IntegrityError): await db.commit()
    await db.rollback(); assert await verify_accounting_equation(db, test_user_id, base_currency='SGD') is True
