    'AC-ledger.5.2 AC-audit.global-invariant.1'; entries_data = [(asset_account.id, Direction.DEBIT, equity_account.id, Direction.CREDIT, '10000'), (asset_account.id, Direction.DEBIT, income_account.id, Direction.CREDIT, '3000'), (expense_account.id, Direction.DEBIT, asset_account.id, Direction.CREDIT, '500'), (expense_account.id, Direction.DEBIT, liability_account.id, Direction.CREDIT, '200')]
    for (debit_acc, debit_dir, credit_acc, credit_dir, amount) in entries_data: entry = JournalEntry(user_id=test_user_id, entry_date=date.today(), memo='Test entry', source_type=JournalEntrySourceType.MANUAL, status=JournalEntryStatus.POSTED); db.add(entry); await db.flush(); db.add(JournalLine(journal_entry_id=entry.id, account_id=debit_acc, direction=debit_dir, amount=Decimal(amount), currency='SGD')); db.add(JournalLine(journal_entry_id=entry.id, account_id=credit_acc, direction=credit_dir, amount=Decimal(amount), currency='SGD')); await db.commit()
    result = await verify_accounting_equation(db, test_user_id, base_currency='SGD'); assert result is True; asset_bal = await calculate_account_balance(db, asset_account.id, test_user_id); assert asset_bal == Decimal('12500'); liab_bal = await calculate_account_balance(db, liability_account.id, test_user_id); assert liab_bal == Decimal('200'); equity_bal = await calculate_account_balance(db, equity_account.id, test_user_id); assert equity_bal == Decimal('10000'); income_bal = await calculate_account_balance(db, income_account.id, test_user_id); assert income_bal == Decimal('3000'); expense_bal = await calculate_account_balance(db, expense_account.id, test_user_id); assert expense_bal == Decimal('700')
