async def test_many_lines_complex_salary_correct(db: AsyncSession, test_user_id):
    'AC-ledger.6.4'; accounts_config = [('Bank', AccountType.ASSET), ('CPF Contribution', AccountType.EXPENSE), ('Income Tax Expense', AccountType.EXPENSE), ('Health Insurance', AccountType.EXPENSE), ('Salary Income', AccountType.INCOME), ('Bonus Income', AccountType.INCOME)]; accounts = []
